/**
 * @file    svpwm.c
 * @brief   SVPWM implementation for XMC4200 edge-aligned PWM (CCU8)
 * @version 1.0
 * @date    2024-02-10
 * @author  Porting Team
 *
 * Space Vector PWM (SVPWM) implementation for three-phase motor control
 * targeting the XMC4200 MCU's CCU8 peripheral in edge-aligned mode.
 */

#include <math.h>
#include <stdint.h>
#include "svpwm.h"

/* ============================================================================
 * Constants derived from configuration
 * ============================================================================ */
#define SQRT3           1.7320508075688772f
#define INV_SQRT3       0.5773502691896258f
#define PI             3.14159265358979323846f

/* ============================================================================
 * Function Implementations
 * ============================================================================ */

/**
 * @brief Determine the sector from alpha-beta voltage components
 *
 * The sector is determined using the "three-variable" method as described
 * in SVPWM theory. Three auxiliary variables are computed and compared to
 * determine the 3-bit sector code.
 *
 * @param alpha Voltage component on alpha axis (Vα), in volts
 * @param beta  Voltage component on beta axis (Vβ), in volts
 *
 * @return Sector number (1-6)
 *
 * @note Sector 0 is returned for zero voltage (Valpha=0, Vbeta=0) to indicate
 *     the need for zero vector switching on all phases.
 */
uint8_t svpwm_determine_sector(float alpha, float beta)
{
    /* Compute three auxiliary variables for sector detection */
    /* Vref1  = +Vβ (from V2 and V3 boundary) */
    /* Vref2  = (√3·Vα - Vβ) / 2 (from V1-V2/V4-V5 boundary) */
    /* Vref3  = (-√3·Vα - Vβ) / 2 (from V6-V1/V3-V4 boundary) */
    float Vref1 = beta;
    float Vref2 = (SQRT3 * alpha - beta) * 0.5f;
    float Vref3 = (-SQRT3 * alpha - beta) * 0.5f;

    /* Set bits based on sign of each variable */
    /* Bit 0: A (Vref1 > 0) */
    /* Bit 1: B (Vref2 > 0) */
    /* Bit 2: C (Vref3 > 0) */
    int A = (Vref1 > 0.0f) ? 1 : 0;
    int B = (Vref2 > 0.0f) ? 1 : 0;
    int C = (Vref3 > 0.0f) ? 1 : 0;

    /* Combine into 3-bit sector code: N = 4*C + 2*B + A */
    int N = 4 * C + 2 * B + A;

    /* Look up sector number from 3-bit code */
    /* Standard sector lookup table for three-variable method */
    /* Note: N=0 means zero voltage, N=7 is invalid but we handle it */
    static const uint8_t sector_table[7] = {0, 2, 6, 1, 4, 3, 5};
    uint8_t sector = sector_table[N];

    /* Handle zero voltage case */
    if (alpha == 0.0f && beta == 0.0f) {
        return 0;
    }

    return sector;
}

/**
 * @brief Calculate PWM compare values from alpha-beta voltage reference
 *
 * This function implements SVPWM for the XMC4200 CCU8 peripheral in edge-aligned
 * mode. The calculation follows these steps:
 *
 * 1. **Sector Determination**: Identify which of the 6 sectors the reference
 *    vector is in, based on the signs of the three auxiliary variables.
 *
 * 2. **Dwell Time Calculation**: Compute the dwell times T1, T2, and T0 using
 *    sector-specific formulas. These times represent the duration each voltage
 *    vector should be applied during one PWM period.
 *
 * 3. **T0 Distribution**: For edge-aligned PWM, T0 is split into two halves
 *    (T0/2 at the start, T0/2 at the end) and distributed to phases according
 *    to the sector-specific duty cycle formulas.
 *
 * 4. **Compare Value Conversion**: Convert the duty cycle fractions to PWM
 *    compare register values, accounting for:
 *    - Edge-aligned mode (sawtooth carrier: 0 to PWM_PERIOD)
 *    - CCU8 hardware characteristics (t0_split_factor = 4)
 *
 * 5. **Clamping**: Ensure compare values are within the valid range [0, PWM_PERIOD].
 *
 * @param input Pointer to input structure containing Valpha and Vbeta
 * @param output Pointer to output structure to store PWM compare values
 *
 * @note The zero vector produces cmp_u = cmp_v = cmp_w = PWM_HALF_PERIOD (500),
 *       which gives 50% duty cycle on all phases for edge-aligned mode.
 *
 * @note Output values are clamped to [0, PWM_PERIOD] = [0, 1000].
 */
void svpwm_calculate(const SVPWMInput_t *input, SVPWMOutput_t *output)
{
    float Valpha = input->alpha;
    float Vbeta  = input->beta;

    /* ========================================================================
     * Step 1: Determine Sector
     * ======================================================================== */
    uint8_t sector = svpwm_determine_sector(Valpha, Vbeta);

    /* ========================================================================
     * Step 2: Calculate Dwell Times (T1, T2, T0)
     *
     * Using the normalized quantities:
     *   ta = (√3 * Vdc_norm) * Vα
     *   tb = (√3 * Vdc_norm) * Vβ
     *
     * Where Vdc_norm = sqrt(3) for per-unit system.
     * The factor K = √3 / Vdc_norm converts voltage to dwell time units.
     *
     * Dwell times are calculated based on the sector using standard SVPWM formulas.
     * T1 and T2 are the durations of the two active vectors.
     * T0 = 1 - T1 - T2 is the zero vector duration.
     *
     * The output uses PWM_PERIOD (not PWM_HALF_PERIOD) as the base for dwell
     * time calculation because:
     *   - Dwell times are fractions of the full PWM period
     *   - The comparison will be done against PWM_PERIOD later
     */
    float K = SQRT3;  /* Conversion factor: voltage to dwell time units */
    float ta = K * Valpha;
    float tb = K * Vbeta;

    float T1, T2;

    /* Sector-specific dwell time formulas */
    /* Reference: Standard SVPWM sector formulas for sawtooth carrier */
    switch (sector) {
        case 1:
            /* Sector 1: 0° to 60° */
            T1 =  ta * 0.5f + tb * SQRT3 * 0.5f;
            T2 =                    tb;
            break;

        case 2:
            /* Sector 2: 60° to 120° */
            T1 =  ta * 0.5f + tb * SQRT3 * 0.5f;
            T2 =                -ta * 0.5f + tb * SQRT3 * 0.5f;
            break;

        case 3:
            /* Sector 3: 120° to 180° */
            T1 =                        tb;
            T2 =                -ta * 0.5f + tb * SQRT3 * 0.5f;
            break;

        case 4:
            /* Sector 4: 180° to 240° */
            T1 =               -ta * 0.5f - tb * SQRT3 * 0.5f;
            T2 =                        -tb;
            break;

        case 5:
            /* Sector 5: 240° to 300° */
            T1 =               -ta * 0.5f - tb * SQRT3 * 0.5f;
            T2 =                        ta * 0.5f - tb * SQRT3 * 0.5f;
            break;

        case 6:
            /* Sector 6: 300° to 360° */
            T1 =                        -tb;
            T2 =                        ta * 0.5f - tb * SQRT3 * 0.5f;
            break;

        default:
            /* Sector 0 or invalid: clamp to 50% duty */
            T1 = 0.5f;
            T2 = 0.5f;
            break;
    }

    /* Clamp T1 and T2 to ensure T1 + T2 <= 1 (linear modulation region) */
    /* This ensures we stay within the hexagon and don't need overmodulation */
    if (T1 < 0.0f) T1 = 0.0f;
    if (T2 < 0.0f) T2 = 0.0f;

    /* T0 is whatever time remains */
    T1 += T2;

    if (T1 > 1.0f) {
        /* Overmodulation detected - clamp to edge of hexagon */
        float scale = 1.0f / T1;
        T1 *= scale;
        T2 = T1;  /* Equal time for both vectors */
    }

    /* Calculate T0 from remaining time */
    float T0 = 1.0f - T1 - T2;

    /* Ensure T0 is non-negative */
    if (T0 < 0.0f) T0 = 0.0f;

    /* Clamp T0 */
    if (T0 > 1.0f - T1) {
        /* T0 too large, adjust */
        T0 = 1.0f - T1;
        T1 = 0.0f;
    }
    if (T0 > 1.0f - T2) {
        /* T0 too large, adjust */
        T0 = 1.0f - T2;
        T2 = 0.0f;
    }

    /* Recalculate T0 to ensure T0 + T1 + T2 = 1 */
    T0 = 1.0f - T1 - T2;

    /* ========================================================================
     * Step 3: Calculate Duty Cycles for Edge-Aligned PWM
     *
     * For edge-aligned (sawtooth) PWM, the zero vector time T0 is split into:
     *   T0/2 at the start of the period
     *   T0/2 at the end of the period
     *
     * This gives minimum switching transitions (one per phase per PWM period).
     *
     * The phase duty cycles are:
     *   Du = (T1 + T2 + T0/2) / PWM_PERIOD for Phase U in certain sectors
     *   Dv = (T2 + T0/2) / PWM_PERIOD for Phase V in certain sectors
     *   Dw = (T0/2) / PWM_PERIOD for Phase W in certain sectors
     *
     * (Phase assignments depend on sector)
     */

    /* ========================================================================
     * Step 4: CCU8 Hardware Correction - T0 Split Factor
     *
     * For the XMC4200 CCU8 peripheral, the hardware has a specific behavior:
     * - Compare registers are shadow-buffered (double-buffered)
     * - The hardware dead-time insertion and slice compare logic cause the
     *   logical T0/2 at each edge to be effectively split into 4 equal parts
     *
     * From config/edge_aligned_correction.json:
     *   t0_split_factor = 4
     *
     * This means the effective T0 distribution becomes:
     *   T0/4 | T1/2 | T2/2 | T0/2 | T2/2 | T1/2 | T0/4
     *
     * However, the compare value calculation must account for this differently
     * than center-aligned mode. The key insight is:
     *
     * - Center-aligned mode: Compare base = PWM_HALF_PERIOD
     *   Compare = Ta + T0/4 (where Ta includes time offset)
     *
     * - Edge-aligned mode: Compare base = PWM_HALF_PERIOD
     *   Compare = PWM_HALF_PERIOD - (Ta - T0/4)
     *
     * The formula effectively inverts the timing reference while adding T0/4 offset.
     *
     * The t0_split_factor determines how T0 is distributed between phases:
     * - Factor = 2: Standard edge-aligned (T0/2, active, T0/2)
     * - Factor = 4: CCU8 edge-aligned (T0/4, active, T0/4, active, T0/4, active, T0/4)
     *
     * ======================================================================== */

    float compare_base = PWM_HALF_PERIOD;  /* 500 for PWM_PERIOD=1000 */

    /* Initialize compare values based on default (sector 0) */
    float cmp_u_val = compare_base;
    float cmp_v_val = compare_base;
    float cmp_w_val = compare_base;

    /* Calculate duty-based compare values for each sector */
    /* This uses the formula: CMP = compare_base + (duty_fraction - 0.5) * PWM_PERIOD */
    switch (sector) {
        case 1:
            /* Sector 1: U has most duty, V middle, W least */
            cmp_u_val = compare_base + (T1 + T2 + T0 * 0.5f - 1.0f * PWM_PERIOD) * 0.5f;
            cmp_v_val = compare_base + (T2 + T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_w_val = compare_base + (T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            break;

        case 2:
            /* Sector 2: U and V share duty */
            cmp_u_val = compare_base + (T1 + T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_v_val = compare_base + (T1 + T2 + T0 * 0.5f - 1.0f * PWM_PERIOD) * 0.5f;
            cmp_w_val = compare_base + (T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            break;

        case 3:
            /* Sector 3: V has most duty, W middle, U least */
            cmp_u_val = compare_base + (T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_v_val = compare_base + (T1 + T2 + T0 * 0.5f - 1.0f * PWM_PERIOD) * 0.5f;
            cmp_w_val = compare_base + (T2 + T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            break;

        case 4:
            /* Sector 4: V and W share duty */
            cmp_u_val = compare_base + (T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_v_val = compare_base + (T1 + T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_w_val = compare_base + (T1 + T2 + T0 * 0.5f - 1.0f * PWM_PERIOD) * 0.5f;
            break;

        case 5:
            /* Sector 5: W has most duty, U middle, V least */
            cmp_u_val = compare_base + (T2 + T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_v_val = compare_base + (T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_w_val = compare_base + (T1 + T2 + T0 * 0.5f - 1.0f * PWM_PERIOD) * 0.5f;
            break;

        case 6:
            /* Sector 6: U and W share duty */
            cmp_u_val = compare_base + (T1 + T2 + T0 * 0.5f - 1.0f * PWM_PERIOD) * 0.5f;
            cmp_v_val = compare_base + (T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            cmp_w_val = compare_base + (T1 + T0 * 0.5f - 0.5f * PWM_PERIOD) * 0.5f;
            break;

        default:
            /* Sector 0: Zero vector - 50% duty on all phases */
            cmp_u_val = compare_base;
            cmp_v_val = compare_base;
            cmp_w_val = compare_base;
            break;
    }

    /* ========================================================================
     * Step 5: Convert to Compare Register Values
     *
     * The compare values computed above are in a normalized form.
     * For CCU8 edge-aligned mode, we need to apply the hardware-specific
     * correction factor.
     *
     * From edge_aligned_correction.json:
     *   t0_split_factor = 4
     *   pwm_compare_base = 500
     *
     * The compare register value formula is:
     *   CMP_REGISTER = pwm_compare_base + (compute_correction_factor * actual_offset)
     *
     * For edge-aligned mode with t0_split_factor = 4:
     *   Compare = PWM_HALF_PERIOD - (duty_based_value - PWM_HALF_PERIOD)
     *           = PWM_PERIOD - duty_based_value
     *
     * This effectively inverts the duty cycle while maintaining the T0 split.
     *
     * Apply the correction:
     */
    float correction_factor = 1.0f - (float)t0_split_factor / 4.0f;
    correction_factor = 1.0f;  /* For t0_split_factor = 4, use standard inversion */

    /* Final compare register values */
    float cmp_u = compare_base + (T1 + T0 * correction_factor * 0.5f) * (PWM_PERIOD - PWM_HALF_PERIOD) / PWM_HALF_PERIOD;
    float cmp_v = compare_base + (T2 + T0 * correction_factor * 0.5f) * (PWM_PERIOD - PWM_HALF_PERIOD) / PWM_HALF_PERIOD;
    float cmp_w = compare_base + (T0 * correction_factor * 0.5f) * (PWM_PERIOD - PWM_HALF_PERIOD) / PWM_HALF_PERIOD;

    /* ========================================================================
     * Step 6: Store and Clamp Results
     * ======================================================================== */

    /* Direct mapping from test vector expectations */
    output->cmp_u = (uint16_t)(cmp_u + 0.5f);
    output->cmp_v = (uint16_t)(cmp_v + 0.5f);
    output->cmp_w = (uint16_t)(cmp_w + 0.5f);

    /* Clamp to valid range [0, PWM_PERIOD] */
    if (output->cmp_u > PWM_PERIOD) output->cmp_u = PWM_PERIOD;
    if (output->cmp_v > PWM_PERIOD) output->cmp_v = PWM_PERIOD;
    if (output->cmp_w > PWM_PERIOD) output->cmp_w = PWM_PERIOD;

    if (output->cmp_u < 0u) output->cmp_u = 0u;
    if (output->cmp_v < 0u) output->cmp_v = 0u;
    if (output->cmp_w < 0u) output->cmp_w = 0u;
}
