        {86.6025f, -50.0000f, 6, 779, 221, 500}, // T07
        {162.3336f, 0.0000f, 6, 893, 107, 107},  // T08
        {81.1668f, 140.5850f, 1, 893, 893, 107}, // T09
        {20.0000f, 10.0000f, 1, 562, 494, 438},  // T10
        {40.1209f, 69.2121f, 1, 694, 693, 306},  // T11
        {-120.0000f, 40.0000f, 3, 154, 846, 623} // T12
    };

    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);
    int passed = 0;
    int total = num_tests;

    for (int i = 0; i < num_tests; i++) {
        SVPWMInput_t input;
        SVPWMOutput_t output;

        input.alpha = test_cases[i][0];
        input.beta = test_cases[i][1];

        svpwm_calculate(&input, &output);

        int expected_sector = (int)test_cases[i][2];
        int expected_u = (int)test_cases[i][3];
        int expected_v = (int)test_cases[i][4];
        int expected_w = (int)test_cases[i][5];

        int actual_sector = (expected_sector == 0) ? 0 : output.cmp_u > output.cmp_v && output.cmp_v > output.cmp_w ? 1 : 
                           (output.cmp_u == output.cmp_v && output.cmp_v == output.cmp_w) ? 0 :
                           (output.cmp_u > output.cmp_v && output.cmp_v == output.cmp_w) ? 6 :
                           (output.cmp_u > output.cmp_v && output.cmp_w > output.cmp_v) ? 1 :
                           (output.cmp_u == output.cmp_v && output.cmp_v > output.cmp_w) ? 4 :
                           (output.cmp_u > output.cmp_v && output.cmp_w < output.cmp_v) ? 1 :
                           (output.cmp_u < output.cmp_v && output.cmp_w > output.cmp_v) ? 2 :
                           (output.cmp_u < output.cmp_v && output.cmp_v < output.cmp_w) ? 3 :
                           (output.cmp_u > output.cmp_v && output.cmp_v > output.cmp_w) ? 1 :
                           5;

        int passed_test = (actual_sector == expected_sector) &&
                         (output.cmp_u == expected_u) &&
                         (output.cmp_v == expected_v) &&
                         (output.cmp_w == expected_w);

        if (passed_test) {
            printf("Test %d PASSED: sector=%d u=%d v=%d w=%d\n", i+1, actual_sector, output.cmp_u, output.cmp_v, output.cmp_w);
            passed++;
        } else {
            printf("Test %d FAILED:\n", i+1);
            printf("  Input: alpha=%.2f beta=%.2f\n", input.alpha, input.beta);
            printf("  Expected: sector=%d u=%d v=%d w=%d\n", expected_sector, expected_u, expected_v, expected_w);
            printf("  Actual:   sector=%d u=%d v=%d w=%d\n", actual_sector, output.cmp_u, output.cmp_v, output.cmp_w);
        }
    }

    printf("\n%d/%d tests passed\n", passed, total);

    return 0;
}
